package com.autocare.platform.order;

import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Current-month entitlement evidence only. R7 must recheck when accepting a message. */
public class InviteDiagnosisPolicies {
 private final ReservationStore db;private final OperatorIdentity operators;
 public InviteDiagnosisPolicies(ReservationStore db,OperatorIdentity operators){this.db=db;this.operators=operators;}
 static JsonNode input(String raw,boolean update){var b=CouponInput.parse(raw);if(update)CouponInput.exact(b,"required_count","source_note","valid_from","valid_to","expected_revision");else CouponInput.exact(b,"required_count","source_note","valid_from","valid_to");if(update)CouponInput.version(b.get("expected_revision"));var n=b.get("required_count");if(!n.isIntegralNumber()||!n.canConvertToInt()||n.intValue()<1||n.intValue()>1000000)throw InvitationInput.bad();var s=b.get("source_note");if(!s.isTextual()||!s.textValue().equals(s.textValue().strip())||s.textValue().codePointCount(0,s.textValue().length())<2||s.textValue().codePointCount(0,s.textValue().length())>256||s.textValue().chars().anyMatch(Character::isISOControl))throw InvitationInput.bad();if(!CouponInput.time(b.get("valid_to")).isAfter(CouponInput.time(b.get("valid_from"))))throw InvitationInput.bad();return b;}
 private ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"解锁政策状态或版本已变化，请重新读取");}
 private Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM invite_diagnosis_policy WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 Map<String,Object> view(Map<String,Object> r){var n=new LinkedHashMap<String,Object>();for(String k:List.of("id","revision","status","required_count","source_note"))n.put(k,r.get(k));for(String k:List.of("valid_from","valid_to","created_at","published_at"))n.put(k,iso(r.get(k)));n.put("rule_version","R6B_DIAGNOSIS_V1");return n;}
 public Map<String,Object> list(OperatorActor a,int page){return db.reads.execute(t->{operators.authorize(a,OperatorIdentity.Permission.INVITE,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM invite_diagnosis_policy",Long.class);return page(db.jdbc.queryForList("SELECT * FROM invite_diagnosis_policy ORDER BY id DESC LIMIT 20 OFFSET ?",(page-1)*20L).stream().map(this::view).toList(),count,page,20);});}
 public JsonNode create(OperatorActor a,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"POST","/api/admin/invite/diagnosis-policies",key,b,()->operators.authorize(a,OperatorIdentity.Permission.INVITE,true),()->{if(!CouponInput.time(b.get("valid_to")).isAfter(db.now()))throw conflict();long id=db.insert("INSERT INTO invite_diagnosis_policy(required_count,source_note,valid_from,valid_to,created_by,created_at) VALUES(?,?,?,?,?,?)",b.get("required_count").intValue(),b.get("source_note").textValue(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),a.id(),time(db.now()));var after=view(row(id,true));return new Change("INVITE_DIAGNOSIS_CREATE","invite_diagnosis_policy",id,Map.of(),after,after);});}
 public JsonNode update(OperatorActor a,long id,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/invite/diagnosis-policies/"+id,key,b,()->{operators.authorize(a,OperatorIdentity.Permission.INVITE,true);row(id,true);},()->{var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=b.get("expected_revision").longValue()||!CouponInput.time(b.get("valid_to")).isAfter(db.now()))throw conflict();var before=view(r);db.jdbc.update("UPDATE invite_diagnosis_policy SET required_count=?,source_note=?,valid_from=?,valid_to=?,revision=revision+1 WHERE id=?",b.get("required_count").intValue(),b.get("source_note").textValue(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),id);var after=view(row(id,true));return new Change("INVITE_DIAGNOSIS_UPDATE","invite_diagnosis_policy",id,before,after,after);});}
 public JsonNode status(OperatorActor a,long id,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/invite/diagnosis-policies/"+id+"/status",key,b,()->{operators.authorize(a,OperatorIdentity.Permission.INVITE,true);row(id,true);},()->{var r=row(id,true);String target=b.get("status").textValue();if(number(r,"revision")!=b.get("expected_revision").longValue()||!(target.equals("PUBLISHED")?"DRAFT".equals(r.get("status")):"PUBLISHED".equals(r.get("status"))))throw conflict();if(target.equals("PUBLISHED")&&(!instant(r.get("valid_to")).isAfter(db.now())||!db.jdbc.queryForList("SELECT id FROM invite_diagnosis_policy WHERE status='PUBLISHED'").isEmpty()))throw conflict();var before=view(r);try{db.jdbc.update("UPDATE invite_diagnosis_policy SET status=?,revision=revision+1,published_at=? WHERE id=?",target,target.equals("PUBLISHED")?time(db.now()):r.get("published_at"),id);}catch(org.springframework.dao.DuplicateKeyException e){throw conflict();}var after=view(row(id,true));return new Change("INVITE_DIAGNOSIS_STATUS","invite_diagnosis_policy",id,before,after,after);});}
 public Map<String,Object> current(VehicleOwner a){return db.reads.execute(t->{db.owner(a,false);var out=eligibility(a.id());out.put("service_available","ELIGIBLE".equals(out.get("state"))&&Boolean.TRUE.equals(DiagnosisServicePolicies.availability(db).get("accepting")));return out;});}
 /** Must execute within the accepting transaction and revalidate actor there in R7. */
 Map<String,Object> eligibility(long user){return eligibility(user,false);}
 Map<String,Object> eligibility(long user,boolean lock){
  var now=db.now();var zone=ZoneId.of("Asia/Shanghai");var first=now.atZone(zone).toLocalDate().withDayOfMonth(1).atStartOfDay(zone);var next=first.plusMonths(1);String month=first.toLocalDate().toString().substring(0,7);
  long count=lock?db.jdbc.queryForList("SELECT r.user_id FROM invite_registration r JOIN `user` u ON u.id=r.user_id AND u.status=1 AND u.is_deleted=0 WHERE r.source_type='user' AND r.source_id=? AND r.attribution_result='ATTRIBUTED' AND r.identity_source='VERIFIED_WECHAT' AND r.qualification_status='QUALIFIED' AND r.reward_month=? AND r.qualified_at>=? AND r.qualified_at<? FOR UPDATE",user,month,time(first.toInstant()),time(next.toInstant())).size():db.jdbc.queryForObject("SELECT COUNT(*) FROM invite_registration r JOIN `user` u ON u.id=r.user_id AND u.status=1 AND u.is_deleted=0 WHERE r.source_type='user' AND r.source_id=? AND r.attribution_result='ATTRIBUTED' AND r.identity_source='VERIFIED_WECHAT' AND r.qualification_status='QUALIFIED' AND r.reward_month=? AND r.qualified_at>=? AND r.qualified_at<?",Long.class,user,month,time(first.toInstant()),time(next.toInstant()));
  var out=new LinkedHashMap<String,Object>();out.put("month",month);out.put("timezone","Asia/Shanghai");out.put("qualified_count",count);out.put("state","UNKNOWN");out.put("policy",null);out.put("usable_until",null);out.put("service_available",false);out.put("rule_version","R6B_DIAGNOSIS_V1");
  var rows=db.jdbc.queryForList("SELECT * FROM invite_diagnosis_policy WHERE status='PUBLISHED'"+(lock?" FOR UPDATE":""));if(rows.isEmpty())return out;var p=rows.get(0);out.put("policy",view(p));String state=instant(p.get("valid_from")).isAfter(now)?"NOT_STARTED":!instant(p.get("valid_to")).isAfter(now)?"EXPIRED":count<number(p,"required_count")?"LOCKED":"ELIGIBLE";out.put("state",state);if(state.equals("ELIGIBLE"))out.put("usable_until",(instant(p.get("valid_to")).isBefore(next.toInstant())?instant(p.get("valid_to")):next.toInstant()).toString());return out;
 }
}
